1.2.8 Ссылочные переменные
В языке C++ введен новый составной тип данных – ссылочная
переменная. Ссылка представляет собой имя, которое является
псевдонимом для ранее объявленной переменной. Для объявления
ссылочной переменной используется символ «&».
Пример:
#include <iostream>
using namespace std;
int main()
{ int x;
int &r = x; // создание независимой ссылки
x = 10; // эти две инструкции
r = 10; // идентичны
return 0;
}
Основное назначение ссылок – использование в качестве
формальных параметров функций. Используя ссылку в качестве
аргумента, функция работает с исходными данными, а не с их
копиями.
Пример передачи аргументов по ссылке (функция, меняющая
значения аргументов):
#include <iostream>
using namespace std;
void swapargs (int &x, int &y);
int main()
{ int i, j;
i = 10;
j = 19;
cout << "i: " << i << ", "; cout << "j: " << j << "\n";
swapargs(i, j);
cout << "После перестановки: ";
cout << "i: " << i << ", "; cout << "j: " << j << "\n"; return 0;
}
void swapargs (int &x, int &y)
{ int t;
t = x; x = y; y = t;
}
