2. МЕТОДИКА ВЫПОЛНЕНИЯ
1. Ознакомиться с приведенным ниже текстом программы
консольного приложения, в котором создаются 2 потока одного
процесса, выполняющие увеличение глобальной переменной. Для
синхронизации доступа конкурирующих потоков к переменной
используется неименованный объект ядра – mutex.
#include <windows.h>
#include <iostream>
using namespace std;
int global = 100; // глобальная переменная, значение которой увеличивают потоки
DWORD Tid1, Tid2;
HANDLE hT1, hT2;
HANDLE hMx;
// функция первого потока
DWORD WINAPI ThreadProc1( LPVOID lpParameter )
{
int i, j;
for (j=1; j <= 12; j++)
{
WaitForSingleObject(hMx, INFINITE);
// начало критического участка
i = global;
i++;
Sleep (1);
global = i;
// конец критического участка
printf_s( "%4s %4d \n", " 1 th", i );
ReleaseMutex(hMx);
}
return 0;
}
// функция второго потока
DWORD WINAPI ThreadProc2 (LPVOID lpParameter)
{
int i, j;
for (j=1; j <= 12; j++)
{
WaitForSingleObject (hMx, INFINITE);
// начало критического участка
i = global;
i++;
Sleep (1);
global = i;
// конец критического участка
64

printf_s( "%4s %4d %4d \n", " 2 th", i, j );
ReleaseMutex(hMx);
}
return 0;
}
// основной поток
int main()
{
HANDLE msh[2];
hMx = CreateMutex(NULL, FALSE, NULL);
hT1 = CreateThread(NULL, 0, &ThreadProc1, NULL, 0, &Tid1);
hT2 = CreateThread(NULL, 0, &ThreadProc2, NULL, 0, &Tid2);
msh[0] = hT1;
msh[1] = hT2;
// ожидание завершения работы потоков
if (WaitForMultipleObjects(2, msh,TRUE,1000)==WAIT_TIMEOUT)
printf_s("Over time");
return 0;
}
В рассмотренном приложении два потока ThreadProc1 и
ThreadProc2 при каждом выполнении цикла увеличивают значение
глобальной переменной global от начального значения 100 на 1.
Число повторений цикла в каждом потоке равно 12.
