1.5 Явное подключение DLL
Явное подключение DLL осуществляется функцией LoadLibrary,
возвращающей дескриптор библиотеки с заданным именем. Этот
дескриптор требуется при вызове всех остальных функций работы с
библиотеками, поэтому его нужно сохранить в переменной.
Загрузка функций из DLL осуществляется с помощью вызова
функции GetProcAddress.
Пример вызова функции из явно подключенной библиотеки:
#include <windows.h>
#include <iostream>
#include <cstdio>
using namespace std;
typedef int (*LibraryFunction)(int, int, int); // определение типа
HMODULE hLib;
hLib = LoadLibrary(L"Dll6a.dll");
if (hLib != NULL) // проверка успешной загрузки библиотеки
{ cout << "Library loaded successfully." << endl;
// загрузка функции
LibraryFunction MyFunction = (LibraryFunction)GetProcAddress(hLib, "MyFunction");
if (MyFunction)
{ cout << "Function loaded successfully." << endl;
Int m = MyFunction(5, 17, 6); // вызов функции из загруженной библиотеки
}
FreeLibrary(hLib);
}
